JavaRDD<String> topFrequentQueries = sparkContext.textFile("/path/to/top_frequent_queries.txt");

// Load the onsite attributed data
JavaRDD<String> onsiteAttributedData = sparkContext.textFile("/path/to/onsite_attributed_data.txt");

// Split the onsite attributed data into key-value pairs (query, timestamp)
JavaPairRDD<String, Long> keyedOnsiteData = onsiteAttributedData.mapToPair(line -> {
    String[] parts = line.split("\t");
    String query = parts[0];
    long timestamp = Long.parseLong(parts[1]);
    return new Tuple2<>(query, timestamp);
});

// Filter the key-value pairs to only include queries that are in the top frequent queries dataset
JavaPairRDD<String, Long> filteredOnsiteData = keyedOnsiteData.filter(pair -> topFrequentQueries.contains(pair._1));

// Track the first occurrence of each query using a stateful transformation
JavaPairRDD<String, Long> firstOccurrence = filteredOnsiteData.mapToPair(pair -> {
    return new Tuple2<>(pair._1, pair._2);
}).reduceByKey((a, b) -> {
    return Math.min(a, b); // Keep the minimum timestamp as the first occurrence
});

// Count the total occurrences of each query
