Map<String, Integer> totalCount = pairFunctions.countByKey().collect();

// Count the number of first occurrences (cache misses)
Map<String, Integer> firstCount = firstOccurrence.pairFunctions().countByKey().collect();

// Calculate the hit rate for each query
Map<String, Double> hitRate = new HashMap<>();
for (Map.Entry<String, Integer> entry : totalCount.entrySet()) {
    String query = entry.getKey();
    Integer total = entry.getValue();
    Integer first = firstCount.get(query);
    if (first != null) {
        double hitRateValue = (total - first) / (double) total;
        hitRate.put(query, hitRateValue);
    }
}

// Print the hit rate for each query
hitRate.forEach((query, rate) -> System.out.println(query + ": " + rate));
